"use strict";(self.webpackChunkstudy_notes=self.webpackChunkstudy_notes||[]).push([[2894],{1921:(t,e,d)=>{d.r(e),d.d(e,{comp:()=>E,data:()=>y});var r=d(9588);const a=d.p+"assets/img/外观1.4c79d6c1.jpg",h=d.p+"assets/img/尺寸.64d2f8c1.jpg",s=d.p+"assets/img/外观2.c01628d2.jpg",o=d.p+"assets/img/1.c60b87a1.jpeg",n=d.p+"assets/img/2.5f93cd9a.jpeg",i=d.p+"assets/img/3.63adb7ee.jpeg",l=d.p+"assets/img/4.ff4cd5e8.jpeg",p=d.p+"assets/img/1.2c119ade.png",c=d.p+"assets/img/2.2eaa5692.jpg",b=d.p+"assets/img/3.427ca9e9.jpg",m=d.p+"assets/img/5.3d39d3ef.jpg",f=d.p+"assets/img/4.1770e915.png",g=d.p+"assets/img/6.4f4550e9.jpg",S=d.p+"assets/img/26284.913a8a0e.jpg",u=d.p+"assets/img/2.4b6bf6ed.jpg",C=d.p+"assets/img/1.cd7fc787.jpg",v=d.p+"assets/img/3.6b11fb73.jpg",M=d.p+"assets/img/4.546c5bc9.jpg",_=d.p+"assets/img/1.8fc57ac3.png",k=d.p+"assets/img/2.ac7f7960.png",A=d.p+"assets/img/3.fa0a89ec.png",B=d.p+"assets/img/ST_MC_SDK.355d47ea.png",O={},E=(0,d(5726).A)(O,[["render",function(t,e){return(0,r.uX)(),(0,r.CE)("div",null,[...e[0]||(e[0]=[(0,r.Fv)('<h1 id="主流开源电机驱动方案盘点" tabindex="-1"><a class="header-anchor" href="#主流开源电机驱动方案盘点"><span>主流开源电机驱动方案盘点</span></a></h1><h2 id="_1-odrive" tabindex="-1"><a class="header-anchor" href="#_1-odrive"><span>1.<a href="https://odriverobotics.com/" target="_blank" rel="noopener noreferrer">ODrive</a></span></a></h2><h3 id="odrive简介" tabindex="-1"><a class="header-anchor" href="#odrive简介"><span>ODrive简介</span></a></h3><p>ODrive是一个开源的直流无刷电机控制系统，它可以实现高性能的电机控制，适用于机器人、无人机、电动滑板等应用。作者是<a href="https://twitter.com/OskarWeigl" target="_blank" rel="noopener noreferrer">Oskar Weigl</a>，是一位瑞士的软件工程师，他在2016年开始了ODrive的开发，目的是为了让高性能的电机控制更加便宜和易用。</p><h3 id="odrive发展" tabindex="-1"><a class="header-anchor" href="#odrive发展"><span>ODrive发展</span></a></h3><ul><li>ODrive v1: 2016年发布，支持12V-24V电压，10A电流，增量式编码器，I2C通信</li><li>ODrive v2: 2016年发布，支持12V-48V电压，20A电流，增量式编码器，USB通信</li><li>ODrive v3: 2017年发布，支持8V-56V电压，30A电流，增量式编码器，霍尔传感器，USB通信</li><li>ODrive v3.5: 2018年发布，支持8V-56V电压，45A电流，增量式编码器，霍尔传感器，USB通信</li><li><a href="https://github.com/odriverobotics/ODrive" target="_blank" rel="noopener noreferrer">ODrive v3.6</a>: 2019年发布，支持8V-56V电压，60A电流，增量式编码器，霍尔传感器，绝对值编码器，USB通信</li><li>ODrive Pro(该版本固件没有开源): 2021年发布，支持15V-58V电压，80A电流，绝对值编码器，RS485通信</li></ul><h3 id="主要版本介绍" tabindex="-1"><a class="header-anchor" href="#主要版本介绍"><span>主要版本介绍</span></a></h3><h4 id="odrive-v3-6" tabindex="-1"><a class="header-anchor" href="#odrive-v3-6"><span>ODrive v3.6</span></a></h4><table><thead><tr><th>功能</th><th>参数(来源于<a href="https://odriverobotics.com/shop/odrive-v36" target="_blank" rel="noopener noreferrer">官网</a>)</th><th>补充说明</th></tr></thead><tbody><tr><td>电源电压</td><td>12V ~ 56V</td><td></td></tr><tr><td>峰值电流</td><td>每个电机的峰值电流为 120A</td><td></td></tr><tr><td>持续电流</td><td>可达60A</td><td>取决于散热条件：<a href="https://discourse.odriverobotics.com/t/odrive-mosfet-temperature-rise-measurements-using-the-onboard-thermistor/972/5" target="_blank" rel="noopener noreferrer">详细信息</a></td></tr><tr><td>控制模式</td><td>位置、速度和电流控制模式</td><td></td></tr><tr><td>参数辨识</td><td>电感、电阻</td><td></td></tr><tr><td>通信支持</td><td>USB(4000 float/s)、UART、CAN、PWM</td><td></td></tr><tr><td>码盘支持</td><td>增量式编码器、霍尔传感器、绝对值编码器</td><td></td></tr></tbody></table><p>硬件方案(<a href="https://github.com/odriverobotics/ODriveHardware" target="_blank" rel="noopener noreferrer">github</a>)</p><table><thead><tr><th>MCU</th><th>MOS</th><th>MOS驱动</th><th>电流采样</th><th>电源</th><th>PCB</th></tr></thead><tbody><tr><td>STM32F405RGT6</td><td><a href="https://atta.szlcsc.com/upload/public/pdf/source/20180112/C145537_15157255457011261296.PDF?Expires=4070880000&amp;OSSAccessKeyId=LTAIJDIkh7KmGS1H&amp;Signature=8kUkxRdq%2BUGdAMDqSPgSqtBOhPs%3D&amp;response-content-disposition=attachment%3Bfilename%3DC145537_N%25E6%25B2%259F%25E9%2581%259360V%25E5%258D%2595N%25E6%25B2%259F%25E9%2581%2593%25EF%25BC%258C%25E5%258A%259F%25E7%258E%2587MOSFET%25EF%25BC%258C60V%25EF%25BC%258C150A%25EF%25BC%258C2.4M%25CE%25A9_2018-01-12.PDF" target="_blank" rel="noopener noreferrer">NTMFS5C628NLT</a> (48V版本，双路并联)、NTMFS4935NT1G(24V版本)</td><td>drv8301</td><td>0.5mΩ 1% 3W采样电阻，双电阻采样</td><td>-</td><td>4层</td></tr></tbody></table><table><thead><tr><th>外观</th><th>尺寸</th></tr></thead><tbody><tr><td><img src="'+a+'" alt="图片"></td><td><img src="'+h+'" alt="图片"></td></tr><tr><td><img src="'+s+'" alt="图片"></td><td></td></tr></tbody></table><h4 id="odrivepro" tabindex="-1"><a class="header-anchor" href="#odrivepro"><span>ODrivePro</span></a></h4><table><thead><tr><th>功能</th><th>参数(来源官方帮助<a href="https://docs.odriverobotics.com/v/latest/getting-started.html" target="_blank" rel="noopener noreferrer">文档</a>）</th><th>补充说明</th></tr></thead><tbody><tr><td>电源电压</td><td>15V ~ 58V</td><td></td></tr><tr><td>峰值电流</td><td>峰值电流为 120A</td><td></td></tr><tr><td>持续电流</td><td>20A 无冷却、80A 主动散热、120A 峰值(最多3S)</td><td></td></tr><tr><td>控制模式</td><td>位置、速度、电流、轨迹控制</td><td></td></tr><tr><td>通信支持</td><td>USB、UART、CAN-FD、PWM、模拟输入</td><td>关于CAN-FD，最新的固件(0.6.6_2023.4.12)还未支持</td></tr><tr><td>码盘支持</td><td>增量式编码器、霍尔传感器、绝对值编码器、无感模式</td><td></td></tr><tr><td>其他</td><td>支持能量制动回收</td><td>官网只提了一句，没有找到更详细的说明</td></tr></tbody></table><table><thead><tr><th>外观</th><th></th></tr></thead><tbody><tr><td><img src="'+o+'" alt="图片"></td><td><img src="'+n+'" alt="图片"></td></tr><tr><td><img src="'+i+'" alt="图片"></td><td><img src="'+l+'" alt="图片"></td></tr></tbody></table><h3 id="知名应用" tabindex="-1"><a class="header-anchor" href="#知名应用"><span>知名应用</span></a></h3><p>  目前看到的使用ODrive的项目主要集中在：电动滑板车、四足机器人、平衡车、电动自行车等方向。如日本仿生机器人、斯坦福Doggo机器狗，还有稚晖君的<a href="https://www.bilibili.com/video/BV11V41127pq" target="_blank" rel="noopener noreferrer">驱动器</a>也基于ODrive。</p><hr><h2 id="_2-simplefoc" tabindex="-1"><a class="header-anchor" href="#_2-simplefoc"><span>2.<a href="https://www.simplefoc.com/" target="_blank" rel="noopener noreferrer">SimpleFOC</a></span></a></h2><h3 id="simplefoc简介" tabindex="-1"><a class="header-anchor" href="#simplefoc简介"><span>SimpleFOC简介</span></a></h3><p>SimpleFOC是一种基于Arduino的FOC算法库，可以用于无刷直流电机和步进电机的控制。SimpleFOC的目标是提供一种简单易用，高性能，低成本的电机控制方案，让用户可以快速地实现电机的速度控制、位置控制和力矩控制。作者是<a href="https://askuric.github.io/" target="_blank" rel="noopener noreferrer">Antun Skuric</a>，是一位法国的电气工程师。</p><h3 id="simplefoc发展" tabindex="-1"><a class="header-anchor" href="#simplefoc发展"><span>SimpleFOC发展</span></a></h3><ul><li>2019年4月，SimpleFOC项目开始，最初只支持无刷直流电机的控制。</li><li>2019年8月，v1.0.0，支持Arduino Uno和Arduino Nano等开发板。</li><li>2019年11月，v1.5.0，增加了对步进电机的控制支持，以及对Arduino Due和Teensy等开发板的支持。</li><li>2020年3月，v1.6.0，增加了对霍尔传感器和绝对编码器的支持，以及对STM32等开发板的支持。</li><li>2020年7月，v2.0.0，增加了对多轴电机控制的支持，以及对ESP32等开发板的支持。</li><li>2020年12月，v2.1.0，增加了对电流控制模式和力矩控制模式的支持，以及对Arduino MKR等开发板的支持。</li><li>2021年4月，v2.2.0，增加了对电机参数自动识别和调试功能的支持，以及对Arduino Nano 33 BLE等开发板的支持。</li><li>2023年4月，v2.3.0，增加了对更多电机和处理器的支持，以及优化了一些<a href="https://docs.simplefoc.com/docs_chinese/" target="_blank" rel="noopener noreferrer">细节</a></li></ul><h3 id="一些硬件版本" tabindex="-1"><a class="header-anchor" href="#一些硬件版本"><span>一些硬件版本</span></a></h3><table><thead><tr><th>型号</th><th>功率</th><th>实物</th><th></th></tr></thead><tbody><tr><td>SimpleFOCMini</td><td>&lt;3A</td><td><img src="'+p+'" alt="图片"></td><td><img src="'+c+'" alt="图片"></td></tr><tr><td>SimpleFOCShield</td><td>&lt;5A</td><td><img src="'+b+'" alt="图片"></td><td><img src="'+m+'" alt="图片"></td></tr><tr><td>SimpleFOCPowerShield</td><td>&lt;30A</td><td><img src="'+f+'" alt="图片"></td><td><img src="'+g+'" alt="图片"></td></tr></tbody></table><p>SimpleFOCPowerShield硬件方案(<a href="https://github.com/simplefoc/Arduino-SimpleFOC-PowerShield" target="_blank" rel="noopener noreferrer">github</a>)</p><table><thead><tr><th>MCU</th><th>MOS</th><th>MOS驱动</th><th>电流采样</th><th>电源</th><th>PCB</th></tr></thead><tbody><tr><td>无</td><td><a href="https://atta.szlcsc.com/upload/public/pdf/source/20220204/C2653440_702986052287C1B0960238BAE5FC3054.pdf" target="_blank" rel="noopener noreferrer">BTN8982</a></td><td>BTN8982</td><td>1mΩ 双电阻采样</td><td>无</td><td>2层</td></tr></tbody></table><hr><h2 id="_3-vesc-本杰明电调" tabindex="-1"><a class="header-anchor" href="#_3-vesc-本杰明电调"><span>3.<a href="https://vesc-project.com" target="_blank" rel="noopener noreferrer">VESC（本杰明电调）</a></span></a></h2><h3 id="简介" tabindex="-1"><a class="header-anchor" href="#简介"><span>简介</span></a></h3><p>VESC 是一个开源的无刷电机驱动器，是由瑞典的工程师<a href="http://vedder.se/" target="_blank" rel="noopener noreferrer">本杰明·维德尔（Benjamin Vedder）</a>开发的，最初应用于电动滑板，但是由于其出色的性能，也渐渐在其他领域得到了应用(电动助力自行车， 山地车，电动滑板，越野滑板，越野scooter ，平衡车，独轮车，航模飞机，)。</p><h3 id="发展" tabindex="-1"><a class="header-anchor" href="#发展"><span>发展</span></a></h3><ul><li>2014年，本杰明发布了VESC 4.0的硬件设计和固件源码，这是第一个公开的版本。</li><li>2015年，本杰明发布了VESC 4.10和4.11的硬件设计，增加了一些新的功能和改进。</li><li>2016年，本杰明发布了VESC 4.12的硬件设计，这是目前最流行的版本之一。</li><li>2017年，本杰明发布了VESC 6.0的硬件设计和固件源码，这是一个全新的版本，提高了性能和可靠性(开始支持FOC)。</li><li>2018年，本杰明发布了VESC Tool软件，这是一个用于配置和控制VESC的图形界面程序。</li><li>2019年，本杰明发布了VESC HD60和HD75的硬件设计，这是一些高功率的版本，适用于更大的电机和负载。</li><li>2020年，本杰明发布了VESC 75/300的硬件设计，这是一个超高功率的版本，可以驱动300A的电流。</li><li>2021年，本杰明发布了VESC FW5.3的固件源码，这是目前最新的固件版本。</li></ul><h3 id="vesc主要版本介绍" tabindex="-1"><a class="header-anchor" href="#vesc主要版本介绍"><span>VESC主要版本介绍</span></a></h3><h4 id="vesc-75-300" tabindex="-1"><a class="header-anchor" href="#vesc-75-300"><span>VESC 75/300</span></a></h4><table><thead><tr><th>功能</th><th>参数(来源于<a href="https://trampaboards.com/vesc-75v-300a-black-anodised-non-conductive-cnc-housing--the-most-powerful-vedder-electronic-speed-controller-ever-p-26284.html" target="_blank" rel="noopener noreferrer">官网</a>)</th><th>补充说明</th></tr></thead><tbody><tr><td>电源电压</td><td>14V ~ 67V,电压尖峰不得超过 75V</td><td></td></tr><tr><td>峰值电流</td><td>450A</td><td></td></tr><tr><td>持续电流</td><td>可达300A</td><td>取决于散热条件</td></tr><tr><td>通信支持</td><td>USB、CAN、UART、PPM、模拟、NRF Nyko Kama Nunchuck</td><td></td></tr><tr><td>码盘支持</td><td>ABI、HALL、AS5047、SIN-COS RMB29（在 COMM 端口上）</td><td></td></tr><tr><td>其他</td><td>带IMU</td><td></td></tr></tbody></table><p>硬件方案(<a href="https://vesc-project.com/node/311" target="_blank" rel="noopener noreferrer">官网</a>)</p><table><thead><tr><th>MCU</th><th>MOS</th><th>MOS驱动</th><th>电流采样</th><th>电源</th><th>PCB</th></tr></thead><tbody><tr><td>STM32F405RGT6</td><td><a href="https://atta.szlcsc.com/upload/public/pdf/source/20200513/C533296_51CD726AEEA63EC1F9FFF5B2FD4FA5BA.pdf" target="_blank" rel="noopener noreferrer">IRF7759</a> 3路并联</td><td><a href="https://www.ti.com/cn/lit/ds/symlink/ucc27211.pdf?ts=1682588025815&amp;ref_url=https%253A%252F%252Fso.szlcsc.com%252Fglobal.html%253Fk%253DUCC2721%2526hot-key%253DMSP430F149IPMR" target="_blank" rel="noopener noreferrer">UCC2721</a></td><td>0.5mΩ 三电阻采样（三电阻并联，相电流采样）</td><td>-</td><td>只提供原理图支持，不提高layout</td></tr></tbody></table><table><thead><tr><th>外观</th></tr></thead><tbody><tr><td><img src="'+S+'" alt="图片"></td></tr></tbody></table><hr><h2 id="_4-mjbots" tabindex="-1"><a class="header-anchor" href="#_4-mjbots"><span>4.<a href="https://mjbots.com/" target="_blank" rel="noopener noreferrer">MJBOTS</a></span></a></h2><h3 id="mjbots简介" tabindex="-1"><a class="header-anchor" href="#mjbots简介"><span>MJBOTS简介</span></a></h3><p>MJBOTS项目是一个开源的机器人系统，它提供了高性能的机器人部件和平台，让用户可以自由地定制和修改。MJBOTS项目的目标是推动机器人技术的发展和普及。创始人是<a href="https://jpieper.com/" target="_blank" rel="noopener noreferrer">Josh Pieper</a>，是一位资深的机器人工程师。曾经在Boston Dynamics工作过，参与了BigDog和Spot等知名的四足机器人的开发。于2019年离开谷歌，开始了MJBOTS项目。B站上有一个搬运YouTube的视频，叫做与<a href="https://www.bilibili.com/video/BV1uq4y1J7Q9/" target="_blank" rel="noopener noreferrer">四足机器人大佬面对面mjbots with Josh Pieper</a></p><p>moteus是MJBOTS项目的一个子项目，它是一种无刷伺服电机驱动器，可以用于机器人的关节驱动。moteus的设计包括了固件和电路板，它可以实现高性能、高效率、高精度的电机控制。moteus的代码和资料都是开源的，可以在<a href="https://github.com/mjbots/moteus" target="_blank" rel="noopener noreferrer">GitHub</a>上找到。</p><h3 id="mjbots发展" tabindex="-1"><a class="header-anchor" href="#mjbots发展"><span>MJBOTS发展</span></a></h3><ul><li>从2019年开始，截止目前github上最近的一次提交记录是20230323，共用27个<a href="https://github.com/mjbots/moteus/releases" target="_blank" rel="noopener noreferrer">Releases</a>。硬件上，<a href="https://mjbots.com/products/moteus-r4-11" target="_blank" rel="noopener noreferrer">moteus r4.11</a>和<a href="https://mjbots.com/products/moteus-n1" target="_blank" rel="noopener noreferrer">moteus-n1</a>是目前最主要的两个版本。</li></ul><h3 id="mjbots主要版本介绍" tabindex="-1"><a class="header-anchor" href="#mjbots主要版本介绍"><span>MJBOTS主要版本介绍</span></a></h3><h4 id="moteus-r4-11" tabindex="-1"><a class="header-anchor" href="#moteus-r4-11"><span>moteus r4.11</span></a></h4><table><thead><tr><th>功能</th><th>参数</th><th>补充说明</th></tr></thead><tbody><tr><td>电源电压</td><td>10V ~ 44V</td><td></td></tr><tr><td>峰值电流</td><td>峰值相电流 100A</td><td>峰值功率500W</td></tr><tr><td>通信支持</td><td>CAN-FD</td><td></td></tr><tr><td>码盘支持</td><td>磁编码盘</td><td></td></tr></tbody></table><p>硬件方案</p><table><thead><tr><th>MCU</th><th>MOS</th><th>MOS驱动</th><th>电流采样</th><th>电源</th><th>PCB</th></tr></thead><tbody><tr><td>STM32G474CEU6</td><td>TPH2R506</td><td>drv8353FS</td><td>-</td><td>-</td><td>-</td></tr></tbody></table><table><thead><tr><th>外观</th><th></th></tr></thead><tbody><tr><td><img src="'+u+'" alt="图片"></td><td><img src="'+C+'" alt="图片"></td></tr></tbody></table><h4 id="moteus-n1" tabindex="-1"><a class="header-anchor" href="#moteus-n1"><span>moteus n1</span></a></h4><table><thead><tr><th>功能</th><th>参数</th><th>补充说明</th></tr></thead><tbody><tr><td>电源电压</td><td>10V ~ 54V</td><td></td></tr><tr><td>峰值电流</td><td>峰值相电流 100A</td><td>峰值功率1200W</td></tr><tr><td>通信支持</td><td>CAN-FD、SPI、UART、422</td><td></td></tr><tr><td>码盘支持</td><td>磁编码盘、正交、霍尔</td><td></td></tr></tbody></table><p>硬件方案</p><table><thead><tr><th>MCU</th><th>MOS</th><th>MOS驱动</th><th>电流采样</th><th>电源</th><th>PCB</th></tr></thead><tbody><tr><td>STM32G474CEU6</td><td>-</td><td>drv8353FS</td><td>-</td><td>-</td><td>-</td></tr></tbody></table><table><thead><tr><th>外观</th><th></th></tr></thead><tbody><tr><td><img src="'+v+'" alt="图片"></td><td><img src="'+M+'" alt="图片"></td></tr></tbody></table><h3 id="应用项目" tabindex="-1"><a class="header-anchor" href="#应用项目"><span>应用项目</span></a></h3><p><a href="https://www.youtube.com/watch?v=ePdGshbKR-Q" target="_blank" rel="noopener noreferrer">robot dog</a></p><hr><h2 id="_5-mit猎豹" tabindex="-1"><a class="header-anchor" href="#_5-mit猎豹"><span>5.<a href="https://biomimetics.mit.edu/" target="_blank" rel="noopener noreferrer">MIT猎豹</a></span></a></h2><h3 id="mit简介" tabindex="-1"><a class="header-anchor" href="#mit简介"><span>MIT简介</span></a></h3><p>MIT猎豹项目是一个由MIT生物机器人实验室（Biomimetic Robotics Lab）发起和领导的研究四足机器人的项目。该项目的目标是开发能够在复杂的环境中灵活地运动的机器人，模仿真实的猎豹的速度和敏捷性。该项目已经开发了多种型号的猎豹机器人，如Cheetah 1，Cheetah 2，Cheetah 3和Mini Cheetah2。这些机器人能够实现跑步，跳跃，翻滚，后退和转弯等动作2。其中，Cheetah Mini是世界上第一款能够后空翻的四足机器人。该项目还利用了强化学习的技术，让机器人能够从模拟器和实际经验中学习如何行走。MIT猎豹项目是一个具有创新性和前瞻性的机器人研究项目，为未来的机器人应用提供了新的可能性。</p><p>lab 成员 Benjamin Katz 在他的<a href="https://dspace.mit.edu/handle/1721.1/118671" target="_blank" rel="noopener noreferrer">硕士论文</a>中开源了 MIT Cheetah Mini 电机驱动器, 连接12个电机与机载电脑的中心板(SPIne)的代码和硬件：</p><ul><li><a href="https://github.com/bgkatz/3phase_integrated" target="_blank" rel="noopener noreferrer">电机控制器硬件</a></li><li><a href="https://os.mbed.com/users/benkatz/code/Hobbyking_Cheetah_Compact_DRV8323/" target="_blank" rel="noopener noreferrer">电机控制器固件</a></li><li><a href="https://github.com/bgkatz/SPIne" target="_blank" rel="noopener noreferrer">SPIne硬件</a></li><li><a href="https://os.mbed.com/users/benkatz/code/SPIne/" target="_blank" rel="noopener noreferrer">SPIne固件</a></li></ul><h3 id="电机控制硬件参数" tabindex="-1"><a class="header-anchor" href="#电机控制硬件参数"><span>电机控制硬件参数</span></a></h3><table><thead><tr><th>功能</th><th>参数</th><th>补充说明</th></tr></thead><tbody><tr><td>电源电压</td><td>24V</td><td>峰值&lt;40V</td></tr><tr><td>峰值电流</td><td>峰值相电流 40A</td><td></td></tr><tr><td>通信支持</td><td>CAN</td><td></td></tr><tr><td>码盘支持</td><td>磁编码盘 AS5047P</td><td></td></tr></tbody></table><p>硬件方案</p><table><thead><tr><th>MCU</th><th>MOS</th><th>MOS驱动</th><th>电流采样</th><th>电源</th><th>PCB</th></tr></thead><tbody><tr><td>STM32F446</td><td>-</td><td>DRV8302</td><td>-</td><td>1mΩ，两相</td><td>-</td></tr></tbody></table><table><thead><tr><th>电机本体及PCB(图片来源于论文)</th></tr></thead><tbody><tr><td><img src="'+_+'" alt="图片"></td></tr><tr><td><img src="'+k+'" alt="图片"></td></tr><tr><td><img src="'+A+'" alt="图片"></td></tr></tbody></table><h3 id="mcsdk应用项目" tabindex="-1"><a class="header-anchor" href="#mcsdk应用项目"><span>MCSDK应用项目</span></a></h3><p>  <a href="https://m.thepaper.cn/baijiahao_14380095" target="_blank" rel="noopener noreferrer">小米铁蛋</a></p><hr><h2 id="_6-st开源电机库" tabindex="-1"><a class="header-anchor" href="#_6-st开源电机库"><span>6.<a href="https://www.st.com/zh/embedded-software/x-cube-mcsdk.html" target="_blank" rel="noopener noreferrer">ST开源电机库</a></span></a></h2><h3 id="mcsdk简介" tabindex="-1"><a class="header-anchor" href="#mcsdk简介"><span>MCSDK简介</span></a></h3><p>ST开源电机库是意法半导体（STMicroelectronics）提供的一基于STM32微控制器的无刷电机控制方案。</p><h3 id="mcsdk发展" tabindex="-1"><a class="header-anchor" href="#mcsdk发展"><span>MCSDK发展</span></a></h3><p>ST电机库发展路线图可参考下图，图片来源于ST官方的培训文档，时间截止2018年</p><ul><li><img src="'+B+'" alt="ST电机库发展路线图"></li><li>ST电机库5.4，发布于2021年，(这个是我目前最熟悉的版本)</li><li>ST电机库6.0，发布于2021年7月，代码以及控制台软件完全重构，目前支持的器件还不多。</li></ul><hr><h2 id="_5-综合对比-待补充" tabindex="-1"><a class="header-anchor" href="#_5-综合对比-待补充"><span>5.综合对比（待补充）</span></a></h2><table><thead><tr><th></th><th>ODrive</th><th>SimpleFOC</th><th>VESC</th><th>MJBOTS</th><th>MIT猎豹</th><th>ST开源库</th></tr></thead><tbody><tr><td>电机类型支持</td><td>----</td><td>----</td><td>----</td><td>----</td><td>----</td><td>----</td></tr><tr><td>控制模式支持</td><td>----</td><td>----</td><td>----</td><td>----</td><td>----</td><td>----</td></tr><tr><td>通信协议支持</td><td>----</td><td>----</td><td>----</td><td>----</td><td>----</td><td>----</td></tr><tr><td>位置传感器支持</td><td>----</td><td>----</td><td>----</td><td>----</td><td>----</td><td>----</td></tr><tr><td>保护功能</td><td>----</td><td>----</td><td>----</td><td>----</td><td>----</td><td>----</td></tr><tr><td>调试功能</td><td>----</td><td>----</td><td>----</td><td>----</td><td>----</td><td>----</td></tr><tr><td>图形界面</td><td>----</td><td>----</td><td>----</td><td>----</td><td>----</td><td>----</td></tr><tr><td>算法支持</td><td>----</td><td>----</td><td>----</td><td>----</td><td>----</td><td>----</td></tr></tbody></table>',82)])])}]]),y=JSON.parse('{"path":"/Embeded/10_Motor/%E6%97%A0%E5%88%B7%E7%94%B5%E6%9C%BA/04%E4%B8%BB%E6%B5%81%E5%BC%80%E6%BA%90%E7%94%B5%E6%9C%BA%E9%A9%B1%E5%8A%A8%E6%96%B9%E6%A1%88%E7%9B%98%E7%82%B9.html","title":"主流开源电机驱动方案盘点","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1768963166000,"contributors":[{"name":"MLH","username":"MLH","email":"mlh18@qq.com","commits":5,"url":"https://github.com/MLH"}],"changelog":[{"hash":"7dd0ae9b3333cbeaee5de4c256045d12fe30028b","time":1768963166000,"email":"mlh18@qq.com","author":"MLH","message":"修改编译错误"},{"hash":"73474a7d8ec37132be0dff9a4362d1e988fd5af9","time":1768962535000,"email":"mlh18@qq.com","author":"MLH","message":"修改编译错误"},{"hash":"1c4cca84f985dc93c9d423934cde3690709494f6","time":1768901688000,"email":"mlh18@qq.com","author":"MLH","message":"修改编译不通过的问题"},{"hash":"ca752a1f1d94e22600afb6cccf3af35af5cf23a6","time":1768901037000,"email":"mlh18@qq.com","author":"MLH","message":"修改编译不通过问题"},{"hash":"250aa3536198209e18c9e5a45c55cef41e5c2e89","time":1768455649000,"email":"mlh18@qq.com","author":"MLH","message":"增加电机控制文档"}]},"filePathRelative":"Embeded/10_Motor/无刷电机/04主流开源电机驱动方案盘点.md"}')}}]);